package de.e2n.cdk.constructs;

import java.time.Instant;
import java.util.HashMap;
import software.amazon.awscdk.customresources.AwsCustomResource;
import software.amazon.awscdk.customresources.AwsCustomResourcePolicy;
import software.amazon.awscdk.customresources.AwsSdkCall;
import software.amazon.awscdk.customresources.PhysicalResourceId;
import software.amazon.awscdk.customresources.SdkCallsPolicyOptions;
import software.constructs.Construct;

/**
 * Enables reading SSM parameters at CDK synthesis time, e.g. to retrieve queue ARNs generated by CDK/CloudFormation
 * without using StackDependencies or CloudFormation ImportValue constructs. This avoids hard dependencies
 * between stacks.
 * https://stackoverflow.com/a/59774628
 * Cross-stack references within a Region also work with Fn.ImportValue
 * or StackProps within an app, but have some drawbacks, so SSM is used instead.
 * Background: https://stackoverflow.com/a/64849790
 * AWS RAM can also be used to share SSM parameters across accounts without AWS STS (cross-account reader role).
 */
public class SSMParameterReader extends Construct {

    private final AwsCustomResource customResource;

    public static SSMParameterReader sharedParameter(Construct scope, SharedSSMParameter ssmParameter) {
        var id = ssmParameter.getOwnerAccountId() + ssmParameter.getRegion() + "SSMParameter"
                + ssmParameter.getParameterName();
        var parameterArn = "arn:aws:ssm:" + ssmParameter.getRegion() + ":" + ssmParameter.getOwnerAccountId()
                + ":parameter" + ssmParameter.getParameterName();
        return new SSMParameterReader(scope, id, parameterArn, ssmParameter.getRegion());
    }
    /**
     * Reads an SSM parameter shared across accounts through AWS RAM in the organization.
     * See also {@link SSMParameterRAMWriter(Construct, String, String, String, String)}.
     * https://docs.aws.amazon.com/systems-manager/latest/userguide/parameter-store-shared-parameters.html
     */
    public static SSMParameterReader sharedParameter(
            Construct scope, String id, String region, String ownerAccountId, String parameterName) {
        var parameterArn = "arn:aws:ssm:" + region + ":" + ownerAccountId + ":parameter" + parameterName;
        return new SSMParameterReader(scope, id, parameterArn, region);
    }

    public SSMParameterReader(Construct scope, String id, String parameterName, String region) {
        this(scope, id, parameterName, region, null);
    }

    public SSMParameterReader(Construct scope, String id, SSMParameter ssmParameter) {
        this(
                scope,
                id,
                ssmParameter.getParameterName(),
                ssmParameter.getRegion(),
                ssmParameter.getReaderRole().getRoleArn());
    }

    public SSMParameterReader(Construct scope, String id, String parameterName, String region, String assumeRoleArn) {
        super(scope, id);

        var builder = AwsSdkCall.builder()
                .service("SSM")
                .action("getParameter")
                .parameters(new HashMap<>() {
                    {
                        put("Name", parameterName);
                    }
                })
                .region(region)
                .physicalResourceId(
                        PhysicalResourceId.of(String.valueOf(Instant.now().getEpochSecond())));

        if (assumeRoleArn != null) {
            builder.assumedRoleArn(assumeRoleArn);
        }
        var sdkCall = builder.build();

        var policy = AwsCustomResourcePolicy.fromSdkCalls(SdkCallsPolicyOptions.builder()
                .resources(AwsCustomResourcePolicy.ANY_RESOURCE)
                .build());
        customResource = AwsCustomResource.Builder.create(this, id)
                .onUpdate(sdkCall)
                .policy(policy)
                // https://github.com/aws/aws-cdk/issues/30067
                .installLatestAwsSdk(false)
                .build();
    }

    public String getParameterValue() {
        return customResource.getResponseField("Parameter.Value");
    }
}
